svg.script:
//
const thickness    = 25; // includes stroke
const stroke_width =  5;
{
   let x_x_x = thickness - (stroke_width);
   let y_y_y = thickness - (stroke_width / 2);
   let inset = stroke_width / 2;

   let edge_l = inset;
   let edge_r = 100 - inset;

   let points = [];

   // Top edges:
   points.push([edge_l, edge_l + x_x_x]);
   points.push([edge_l + x_x_x,  edge_l]);

   points.push([50, 50 - x_x_x]);

   points.push([edge_r - x_x_x, edge_l]);
   points.push([edge_r,         x_x_x]);

   // Righthand center-edge point:
   points.push([50 + x_x_x, 50]);

   // Bottom edges:
   points.push([edge_r,         edge_r - x_x_x]);
   points.push([edge_r - x_x_x, edge_r]);

   points.push([50, 50 + x_x_x]);

   points.push([edge_l + x_x_x,  edge_r]);
   points.push([edge_l,          edge_r - x_x_x]);

   // Righthand center-edge point:
   points.push([50 - x_x_x, 50]);

   let path = "";
   for(let i = 0; i < points.length; ++i) {
      if (i == 0)
         path += "M";
      else
         path += " L";
      path += " " + points[i][0] + "," + points[i][1];
   }
   path += " Z";
   document.getElementById("path").setAttribute("d", path);
}
   //
